  8: //       授权窗口由车端节点（velaguard_task_bridge.py）负责计时，到期自动归零。
  9: import fs from 'node:fs';
 10: import net from 'node:net';
 11: import path from 'node:path';
 12: 
 13: const CARS = { 1: '192.168.1.201', 2: '192.168.1.202', 3: '192.168.1.203', 4: '192.168.1.204' };
 14: const T = {
 15:   task: '/velaguard/task',
 16:   control: '/velaguard/control',
 17:   receipt: '/velaguard/receipt',
 18:   heartbeat: '/velaguard/heartbeat',
 19:   cmd: '/controller/cmd_vel',
 20:   scan: '/scan_raw',
 21:   odom: '/odom',
 22: };
 23: const ZONE_ROUTE = { entrance: 'R1', passage: 'R2', exhibit: 'R3', equipment: 'R4' };
 24: const TERMINAL = ['done', 'blocked', 'cancelled', 'timeout'];
 25: 
 26: const argv = process.argv.slice(2);
 27: const command = argv[0] || 'help';
 28: const opt = {};
 29: for (let i = 1; i < argv.length; i++) {
 30:   const token = argv[i];
 31:   if (!token.startsWith('--')) continue;
 32:   const key = token.slice(2);
 33:   const next = argv[i + 1];
 34:   if (next && !next.startsWith('--')) { opt[key] = next; i++; } else { opt[key] = true; }
 35: }
 36: 
 37: const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
 38: const nowMs = () => Date.now();
 39: const stamp = () => new Date().toISOString().replace(/[:.]/g, '-');
 40: const say = (...a) => console.log(...a);
 41: 
 42: function saveEvidence(name, data) {
 43:   fs.mkdirSync('evidence', { recursive: true });
 44:   const file = path.join('evidence', `${name}-${stamp()}.json`);
 45:   fs.writeFileSync(file, JSON.stringify(data, null, 2));
 46:   say(`  证据已保存：${file}`);
 47:   return file;
 48: }
 49: 
 50: function tcpOpen(host, port = 9090, timeout = 1500) {
 51:   return new Promise((resolve) => {
 52:     const sock = net.connect({ host, port });
 53:     const done = (ok) => { try { sock.destroy(); } catch { /* ignore */ } resolve(ok); };
 54:     sock.setTimeout(timeout);
 55:     sock.once('connect', () => done(true));
 56:     sock.once('timeout', () => done(false));
 57:     sock.once('error', () => done(false));
 58:   });
 59: }
 60: 
 61: class Bridge {
 62:   constructor(host) {
 63:     this.host = host;
 64:     this.ws = null;
 65:     this.handlers = new Map();
 66:     this.pending = new Map();
 67:     this.seq = 0;
 68:   }
 69: 
 70:   open(timeoutMs = 6000) {
 71:     return new Promise((resolve, reject) => {
 72:       const ws = new WebSocket(`ws://${this.host}:9090`);
 73:       const timer = setTimeout(() => {
 74:         try { ws.close(); } catch { /* ignore */ }
 75:         reject(new Error('连接超时'));
 76:       }, timeoutMs);
 77:       ws.addEventListener('open', () => { clearTimeout(timer); this.ws = ws; resolve(this); });
 78:       ws.addEventListener('error', () => { clearTimeout(timer); reject(new Error('websocket 错误')); });
 79:       ws.addEventListener('message', (ev) => this._onMessage(ev));
 80:     });
 81:   }
 82: 
 83:   _onMessage(ev) {
 84:     let packet;
 85:     try { packet = JSON.parse(ev.data); } catch { return; }
 86:     if (packet.op === 'publish') {
 87:       for (const cb of this.handlers.get(packet.topic) || []) {
 88:         try { cb(packet.msg); } catch (err) { console.error('处理消息失败：' + err.message); }
 89:       }
 90:     } else if (packet.op === 'service_response') {
 91:       const resolve = this.pending.get(packet.id);
 92:       if (resolve) { this.pending.delete(packet.id); resolve(packet); }
 93:     }
 94:   }
 95: 
 96:   subscribe(topic, type, cb) {
 97:     if (!this.handlers.has(topic)) {
 98:       this.handlers.set(topic, []);
 99:       this.ws.send(JSON.stringify({ op: 'subscribe', topic, type, throttle_rate: 0, queue_length: 50 }));
100:     }
101:     this.handlers.get(topic).push(cb);
102:   }
103: 
104:   publish(topic, type, msg) {
105:     this.ws.send(JSON.stringify({ op: 'publish', topic, type, msg }));
106:   }
107: 
108:   callService(service, args = {}, timeoutMs = 8000) {
109:     return new Promise((resolve) => {
110:       const id = `svc-${++this.seq}`;
111:       const timer = setTimeout(() => { this.pending.delete(id); resolve(null); }, timeoutMs);
112:       this.pending.set(id, (packet) => { clearTimeout(timer); resolve(packet); });
113:       this.ws.send(JSON.stringify({ op: 'call_service', id, service, args }));
114:     });
115:   }
116: 
117:   close() { try { this.ws.close(); } catch { /* ignore */ } }
118: }
119: 
120: function frontClearance(scan, directionRad, halfAngleDeg = 30) {
121:   const half = (halfAngleDeg * Math.PI) / 180;
122:   let nearest = null;
123:   for (let i = 0; i < scan.ranges.length; i++) {
124:     const distance = Number(scan.ranges[i]);
125:     if (!Number.isFinite(distance) || distance < scan.range_min || distance > scan.range_max) continue;
126:     const angle = Math.atan2(
127:       Math.sin(scan.angle_min + i * scan.angle_increment - directionRad),
128:       Math.cos(scan.angle_min + i * scan.angle_increment - directionRad),
129:     );
130:     if (Math.abs(angle) > half) continue;
131:     nearest = nearest === null ? distance : Math.min(nearest, distance);
132:   }
133:   return nearest === null ? null : Number(nearest.toFixed(2));
134: }
135: 
136: function publishString(bridge, topic, obj) {
137:   bridge.publish(topic, 'std_msgs/msg/String', { data: JSON.stringify(obj) });
138: }
139: 
140: // ---------- E1 baseline ----------
141: async function cmdBaseline() {
142:   const result = { at: new Date().toISOString(), command: 'baseline', cars: {} };
143:   let failures = 0;
144:   for (const [num, ip] of Object.entries(CARS)) {
145:     const entry = { ip, tcp9090: await tcpOpen(ip) };
146:     if (entry.tcp9090) {
147:       try {
148:         const bridge = await new Bridge(ip).open();
149:         let odomCount = 0;
150:         let scanCount = 0;
151:         let lastScan = null;
152:         bridge.subscribe(T.odom, 'nav_msgs/msg/Odometry', () => { odomCount++; });
153:         bridge.subscribe(T.scan, 'sensor_msgs/msg/LaserScan', (m) => { scanCount++; lastScan = m; });
154:         await sleep(3000);
155:         entry.odom_hz = Number((odomCount / 3).toFixed(1));
156:         entry.scan_hz = Number((scanCount / 3).toFixed(1));
157:         entry.front_clearance_m = lastScan ? frontClearance(lastScan, 0) : null;
158:         bridge.close();
159:       } catch (err) {
160:         entry.error = err.message;
161:       }
162:     }
163:     const ok = entry.tcp9090 && (entry.odom_hz || 0) >= 5 && (entry.scan_hz || 0) >= 5;
164:     entry.verdict = ok ? 'PASS' : 'FAIL';
165:     if (!ok) failures++;
166:     result.cars[num] = entry;
167:     say(`  ${num}号车 ${ip}  ${entry.verdict}  odom=${entry.odom_hz ?? '-'}Hz  scan=${entry.scan_hz ?? '-'}Hz  前方净空=${entry.front_clearance_m ?? '-'}m`);
168:   }
169:   result.verdict = failures === 0 ? 'PASS' : 'FAIL';
170:   saveEvidence('baseline', result);
171:   say(`E1 只读基线：${result.verdict}`);
172:   return failures === 0 ? 0 : 1;
173: }
174: 
175: // ---------- E2 task ----------
176: async function cmdTask() {
177:   const car = String(opt.car || '1');
178:   const ip = CARS[car];
179:   if (!ip) { say('未知车号：' + car); return 2; }
180:   const zone = String(opt.zone || 'entrance');
181:   const route = String(opt.route || ZONE_ROUTE[zone] || 'R1');
182:   const taskId = String(opt.task || `T-${car}-${nowMs()}`);
183:   const deadline = Number(opt.deadline || 60);
184:   const armed = Boolean(opt.arm);
185:   const task = { task_id: taskId, robot: `robot${car}`, zone, route, cancel: false, deadline_s: deadline };
186: 
187:   if (opt['dry-run']) { say('  任务单（未下发）：' + JSON.stringify(task)); return 0; }
188: 
189:   const bridge = await new Bridge(ip).open();
190:   const timeline = [];
191:   let terminal = null;
192:   bridge.subscribe(T.receipt, 'std_msgs/msg/String', (m) => {
193:     let r;
194:     try { r = JSON.parse(m.data); } catch { return; }
195:     if (r.task_id !== taskId) return;
196:     timeline.push({ at: nowMs(), ...r });
197:     say(`  回执 ${r.status}  reason=${r.reason}  step=${r.step}/${r.total}`);
198:     if (TERMINAL.includes(r.status)) terminal = r;
199:   });
200:   if (armed) {
201:     publishString(bridge, T.control, { cmd: 'arm', seconds: Number(opt.seconds || 120) });
202:     say('  已发送 arm 授权');
203:     await sleep(300);
204:   }
205:   const t0 = nowMs();
206:   publishString(bridge, T.task, task);
207:   say('  已下发任务单：' + JSON.stringify(task));
208:   while (!terminal && nowMs() - t0 < (deadline + 15) * 1000) await sleep(200);
209:   bridge.close();
210: 
211:   const started = timeline.find((e) => e.status === 'started');
212:   const result = {
213:     at: new Date().toISOString(), command: 'task', car, task, armed,
214:     started_latency_ms: started ? started.at - t0 : null,
215:     elapsed_ms: nowMs() - t0,
216:     timeline,
217:     terminal_status: terminal ? terminal.status : null,
218:   };
219:   let verdict = 'FAIL';
220:   let note = '';
221:   if (!started) {
222:     note = '未收到 started 回执（车端节点是否在跑？）';
223:   } else if (!armed) {
224:     verdict = terminal && terminal.status === 'blocked' && String(terminal.reason) === 'not_armed' ? 'PASS' : 'FAIL';
225:     note = '未授权场景应回 blocked/not_armed';
226:   } else if (terminal && terminal.status === 'done') {
227:     verdict = 'PASS';
228:   } else {
229:     note = `终止状态为 ${terminal ? terminal.status : '无'}`;
230:   }
231:   result.verdict = verdict;
232:   result.note = note;
233:   saveEvidence('task', result);
234:   say(`E2 任务单与回执：${verdict}${note ? '（' + note + '）' : ''}  started 时延=${result.started_latency_ms ?? '-'}ms  总耗时=${result.elapsed_ms}ms`);
235:   return verdict === 'PASS' ? 0 : 1;
236: }
237: 
238: // ---------- E5 cancel ----------
239: async function cmdCancel() {
240:   const car = String(opt.car || '1');
241:   const bridge = await new Bridge(CARS[car]).open();
242:   const seen = [];
243:   let cancelled = null;
244:   bridge.subscribe(T.receipt, 'std_msgs/msg/String', (m) => {
245:     let r;
246:     try { r = JSON.parse(m.data); } catch { return; }
247:     seen.push(r);
248:     say(`  回执 ${r.status}  reason=${r.reason}`);
249:     if (r.status === 'cancelled') cancelled = r;
250:   });
251:   publishString(bridge, T.control, { cmd: 'cancel', reason: 'operator_cancel', task_id: opt.task || '' });
252:   const t0 = nowMs();
253:   while (!cancelled && nowMs() - t0 < 10000) await sleep(200);
254:   bridge.close();
255:   const verdict = cancelled ? 'PASS' : 'FAIL';
256:   saveEvidence('cancel', { at: new Date().toISOString(), car, verdict, seen });
257:   say(`E5 取消任务：${verdict}`);
258:   return verdict === 'PASS' ? 0 : 1;
259: }
