261: // ---------- E4 monitor ----------
262: async function cmdMonitor() {
263:   const seconds = Number(opt.seconds || 90);
264:   const timeout = Number(opt.timeout || 30);
265:   const state = {};
266:   const bridges = [];
267:   for (const [num, ip] of Object.entries(CARS)) {
268:     const entry = { ip, last_heartbeat_ms: null, lost_at_ms: null, recovered_at_ms: null, samples: 0 };
269:     state[num] = entry;
270:     try {
271:       const bridge = await new Bridge(ip).open();
272:       bridge.subscribe(T.heartbeat, 'std_msgs/msg/String', () => { entry.samples++; entry.last_heartbeat_ms = nowMs(); });
273:       bridges.push(bridge);
274:     } catch (err) {
275:       entry.error = err.message;
276:     }
277:   }
278:   const t0 = nowMs();
279:   say(`  监听 ${seconds}s，失联阈值 ${timeout}s（在车上杀掉节点即可触发）`);
280:   while (nowMs() - t0 < seconds * 1000) {
281:     await sleep(500);
282:     for (const num of Object.keys(state)) {
283:       const entry = state[num];
284:       if (entry.error || !entry.last_heartbeat_ms) continue;
285:       const quiet = (nowMs() - entry.last_heartbeat_ms) / 1000;
286:       if (quiet > timeout && !entry.lost_at_ms) {
287:         entry.lost_at_ms = nowMs();
288:         say(`  ⚠ ${num}号车判定失联：${quiet.toFixed(1)}s 无心跳 → 该区域应标记顺延`);
289:       } else if (quiet < 3 && entry.lost_at_ms && !entry.recovered_at_ms) {
290:         entry.recovered_at_ms = nowMs();
291:         say(`  ↺ ${num}号车心跳恢复`);
292:       }
293:     }
294:   }
295:   for (const bridge of bridges) bridge.close();
296:   for (const entry of Object.values(state)) delete entry.last_heartbeat_ms;
297:   const lost = Object.entries(state).filter(([, v]) => v.lost_at_ms).map(([k]) => k);
298:   saveEvidence('monitor', { at: new Date().toISOString(), seconds, timeout, state });
299:   say(`E4 失联判定：判出 ${lost.length} 台${lost.length ? '（' + lost.join('/') + ' 号）' : ''}`);
300:   return 0;
301: }
302: 
303: // ---------- E6 zones ----------
304: async function cmdZones() {
305:   const armed = Boolean(opt.arm);
306:   const plan = [['1', 'entrance', 'R1'], ['2', 'passage', 'R2'], ['3', 'exhibit', 'R3'], ['4', 'equipment', 'R4']];
307:   const deadline = Number(opt.deadline || 90);
308:   const runs = {};
309:   for (const [car, zone, route] of plan) {
310:     const taskId = `T-${car}-${nowMs()}-${zone}`;
311:     const bridge = await new Bridge(CARS[car]).open();
312:     const entry = { car, zone, route, task_id: taskId, timeline: [], terminal: null, foreign_receipts: 0 };
313:     bridge.subscribe(T.receipt, 'std_msgs/msg/String', (m) => {
314:       let r;
315:       try { r = JSON.parse(m.data); } catch { return; }
316:       if (r.task_id !== taskId) { entry.foreign_receipts++; return; }
317:       entry.timeline.push(r);
318:       say(`  ${car}号车 ${r.status} (${r.reason})`);
319:       if (TERMINAL.includes(r.status)) entry.terminal = r;
320:     });
321:     runs[car] = { bridge, entry };
322:   }
323:   if (armed) {
324:     for (const car of Object.keys(runs)) publishString(runs[car].bridge, T.control, { cmd: 'arm', seconds: 180 });
325:     say('  已向四车发送 arm 授权');
326:     await sleep(400);
327:   }
328:   const t0 = nowMs();
329:   for (const [car, zone, route] of plan) {
330:     publishString(runs[car].bridge, T.task, {
331:       task_id: runs[car].entry.task_id, robot: `robot${car}`, zone, route, cancel: false, deadline_s: deadline,
332:     });
333:   }
334:   say('  四车任务已并发下发');
335:   while (nowMs() - t0 < (deadline + 20) * 1000) {
336:     if (plan.every(([car]) => runs[car].entry.terminal)) break;
337:     await sleep(300);
338:   }
339:   for (const car of Object.keys(runs)) runs[car].bridge.close();
340:   const summary = plan.map(([car, zone, route]) => {
341:     const entry = runs[car].entry;
342:     return {
343:       car, zone, route,
344:       terminal: entry.terminal ? entry.terminal.status : null,
345:       reason: entry.terminal ? entry.terminal.reason : null,
346:       foreign_receipts: entry.foreign_receipts,
347:       receipts: entry.timeline.length,
348:     };
349:   });
350:   const coverage = {};
351:   for (const row of summary) {
352:     coverage[row.zone] = row.terminal === 'done' ? '已完成'
353:       : row.terminal === 'blocked' ? '阻塞'
354:         : row.terminal === null ? '未开始' : row.terminal;
355:   }
356:   const crossed = summary.some((row) => row.foreign_receipts > 0);
357:   const verdict = !crossed && summary.every((row) => row.terminal) ? 'PASS' : 'FAIL';
358:   saveEvidence('zones', {
359:     at: new Date().toISOString(), armed, summary, coverage, verdict, elapsed_ms: nowMs() - t0,
360:   });
361:   say('  覆盖汇总：' + JSON.stringify(coverage));
362:   say(`E6 四车分区并发：${verdict}${crossed ? '（存在串扰：收到非本车 task_id 的回执）' : ''}  总耗时=${nowMs() - t0}ms`);
363:   return verdict === 'PASS' ? 0 : 1;
364: }
