367: async function cmdStopall() {
368:   for (const [num, ip] of Object.entries(CARS)) {
369:     try {
370:       const bridge = await new Bridge(ip).open();
371:       publishString(bridge, T.control, { cmd: 'stop', reason: 'operator_stopall' });
372:       for (let i = 0; i < 20; i++) {
373:         bridge.publish(T.cmd, 'geometry_msgs/msg/Twist', {
