export function baselineVerdict(entry, minClearance = 0.8) {
  return Boolean(
    entry.tcp9090
    && Number(entry.odom_hz) >= 5
    && Number(entry.scan_hz) >= 5
    && Number(entry.front_clearance_m) >= minClearance
  );
}

export function taskVerdict({ started, terminal, armed, startedLatencyMs, maxStartedLatencyMs = 2000 }) {
  if (!started || startedLatencyMs > maxStartedLatencyMs) return false;
  if (!armed) return terminal?.status === 'blocked' && terminal?.reason === 'not_armed';
  return terminal?.status === 'done';
}

export function cancelVerdict({ taskId, cancelled, velocities }) {
  if (!cancelled || cancelled.task_id !== taskId) return false;
  return velocities.length > 0 && velocities.every((value) => value <= 1e-6);
}

export function monitorVerdict(state, expectedLost = 1) {
  const entries = Object.values(state);
  const observed = entries.filter((entry) => entry.samples > 0);
  const lost = observed.filter((entry) => entry.lost_at_ms);
  return observed.length > 0 && lost.length >= expectedLost;
}

export function zonesVerdict(summary, expected) {
  return summary.every((row) => (
    row.foreign_receipts === 0
    && row.started === true
    && row.terminal === expected[row.car]
  ));
}

export function parseExpectedStatuses(text, cars) {
  const expected = Object.fromEntries(cars.map((car) => [car, 'done']));
  if (!text) return expected;
  for (const item of String(text).split(',')) {
    const [car, status] = item.split(':').map((value) => value.trim());
    if (!cars.includes(car)) throw new Error(`未知车号 ${car}`);
    if (!['done', 'blocked', 'cancelled', 'timeout'].includes(status)) {
      throw new Error(`未知状态 ${status}`);
    }
    expected[car] = status;
  }
  return expected;
}

import json
import math
import unittest
from pathlib import Path

from velaguard_core import (
    StepProgress,
    clearance_speed_scale,
    directional_clearance,
    resolve_task,
    validate_routes,
)


class VelaGuardCoreTest(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        document = json.loads(Path(__file__).with_name("routes.json").read_text(encoding="utf-8"))
        cls.routes = validate_routes(document)

    def test_route_document(self):
        self.assertEqual(set(self.routes), {"R1", "R2", "R3", "R4"})

    def test_resolve_valid_task(self):
        route_id, steps, deadline = resolve_task({
            "task_id": "T-1",
            "robot": "robot1",
            "zone": "entrance",
            "route": "R1",
            "deadline_s": 60,
        }, "robot1", self.routes)
        self.assertEqual(route_id, "R1")
        self.assertEqual(len(steps), 3)
        self.assertEqual(deadline, 60)

    def test_reject_wrong_robot(self):
        with self.assertRaisesRegex(ValueError, "wrong_robot"):
            resolve_task({
                "task_id": "T-1", "robot": "robot2", "zone": "entrance", "route": "R1",
            }, "robot1", self.routes)

    def test_reject_route_zone_mismatch(self):
        with self.assertRaisesRegex(ValueError, "route_zone_mismatch"):
            resolve_task({
                "task_id": "T-1", "robot": "robot1", "zone": "entrance", "route": "R4",
            }, "robot1", self.routes)

    def test_clearance_scale(self):
        self.assertEqual(clearance_speed_scale(0.4, 0.4, 0.8), 0.0)
        self.assertAlmostEqual(clearance_speed_scale(0.6, 0.4, 0.8), 0.5)
        self.assertEqual(clearance_speed_scale(0.8, 0.4, 0.8), 1.0)

    def test_directional_clearance(self):
        ranges = [2.0, 0.7, 0.5, 1.2, 2.0]
        nearest = directional_clearance(
            ranges, -math.pi / 2, math.pi / 4, 0.1, 10.0, 0.0, math.pi / 4,
        )
        self.assertEqual(nearest, 0.5)

    def test_linear_progress_uses_commanded_speed(self):
        progress = StepProgress()
        step = {"action": "forward", "value": 0.3}
        progress.add_motion("forward", 0.04, 0.0, 3.75)
        self.assertFalse(progress.complete(step))
        progress.add_motion("forward", 0.04, 0.0, 3.75)
        self.assertTrue(progress.complete(step))

    def test_rotation_progress(self):
        progress = StepProgress()
        step = {"action": "turn_left", "value": 90}
        progress.add_motion("turn_left", 0.0, 0.5, math.pi)
        self.assertTrue(progress.complete(step))


if __name__ == "__main__":
    unittest.main()

import math


LINEAR_ACTIONS = {
    "forward": 0.0,
    "backward": math.pi,
    "strafe_left": math.pi / 2.0,
    "strafe_right": -math.pi / 2.0,
}
ROTATE_ACTIONS = {"turn_left": 1.0, "turn_right": -1.0}
SUPPORTED_ACTIONS = set(LINEAR_ACTIONS) | set(ROTATE_ACTIONS) | {"wait"}


def normalize_angle(angle):
    return math.atan2(math.sin(angle), math.cos(angle))


def directional_clearance(ranges, angle_min, angle_increment, range_min, range_max,
                          direction_rad, half_angle_rad):
    nearest = None
    for index, raw in enumerate(ranges):
        distance = float(raw)
        if not math.isfinite(distance) or distance < range_min or distance > range_max:
            continue
        ray_angle = angle_min + index * angle_increment
        if abs(normalize_angle(ray_angle - direction_rad)) > half_angle_rad:
            continue
        nearest = distance if nearest is None else min(nearest, distance)
    return nearest


def clearance_speed_scale(clearance_m, stop_m, slow_m):
    if not 0.0 < stop_m < slow_m:
        raise ValueError("stop_m 必须大于 0，并且小于 slow_m")
    if clearance_m <= stop_m:
        return 0.0
    if clearance_m >= slow_m:
        return 1.0
    return (clearance_m - stop_m) / (slow_m - stop_m)


def validate_routes(document):
    routes = document.get("routes")
    if not isinstance(routes, dict) or not routes:
        raise ValueError("routes 必须是非空对象")
    zones = document.get("zones")
    if not isinstance(zones, dict) or not zones:
        raise ValueError("zones 必须是非空对象")
    for zone, route_id in zones.items():
        route = routes.get(route_id)
        if route is None:
            raise ValueError("区域 %s 引用了未知路线 %s" % (zone, route_id))
        if route.get("zone") != zone:
            raise ValueError("区域 %s 与路线 %s 的 zone 不一致" % (zone, route_id))
    for route_id, route in routes.items():
        steps = route.get("steps")
        if not isinstance(steps, list) or not steps:
            raise ValueError("路线 %s 缺少步骤" % route_id)
        for index, step in enumerate(steps):
            action = str(step.get("action", "")).lower()
            if action not in SUPPORTED_ACTIONS:
                raise ValueError("路线 %s 的第 %d 个步骤包含未知动作 %s"
                                 % (route_id, index + 1, action))
            value = float(step.get("seconds" if action == "wait" else "value", 0.0))
            if not math.isfinite(value) or value <= 0.0:
                raise ValueError("路线 %s 的第 %d 个步骤数值无效" % (route_id, index + 1))
    return routes


def resolve_task(payload, expected_robot, routes):
    if not isinstance(payload, dict):
        raise ValueError("任务单必须是对象")
    task_id = payload.get("task_id")
    if not isinstance(task_id, str) or not task_id.strip():
        raise ValueError("missing_task_id")
    if payload.get("robot") != expected_robot:
        raise ValueError("wrong_robot:%s" % payload.get("robot"))
    zone = payload.get("zone")
    if not isinstance(zone, str) or not zone:
        raise ValueError("missing_zone")
    route_id = payload.get("route")
    if not route_id:
        matches = [name for name, route in routes.items() if route.get("zone") == zone]
        if len(matches) != 1:
            raise ValueError("unknown_zone:%s" % zone)
        route_id = matches[0]
    route_id = str(route_id)
    route = routes.get(route_id)
    if route is None:
        raise ValueError("unknown_route:%s" % route_id)
    if route.get("zone") != zone:
        raise ValueError("route_zone_mismatch:%s:%s" % (route_id, zone))
    deadline = float(payload.get("deadline_s", 60.0))
    if not math.isfinite(deadline) or deadline <= 0.0:
        raise ValueError("invalid_deadline")
    return route_id, list(route["steps"]), deadline


class StepProgress:
    def __init__(self):
        self.value = 0.0

    def reset(self):
        self.value = 0.0

    def add_motion(self, action, linear_speed, angular_speed, elapsed_s):
        if elapsed_s < 0.0:
            raise ValueError("elapsed_s 不能小于 0")
        if action in LINEAR_ACTIONS:
            self.value += abs(linear_speed) * elapsed_s
        elif action in ROTATE_ACTIONS:
            self.value += abs(angular_speed) * elapsed_s
        elif action == "wait":
            self.value += elapsed_s
        else:
            raise ValueError("未知动作 %s" % action)

    def complete(self, step):
        action = str(step.get("action", "")).lower()
        if action == "wait":
            target = float(step.get("seconds", step.get("value", 0.0)))
        elif action in LINEAR_ACTIONS:
            target = abs(float(step.get("value", 0.0)))
        elif action in ROTATE_ACTIONS:
            target = abs(math.radians(float(step.get("value", 0.0))))
        else:
            raise ValueError("未知动作 %s" % action)
        return self.value >= target

