import json
import math
from pathlib import Path

from velaguard_core import (
    LINEAR_ACTIONS,
    ROTATE_ACTIONS,
    StepProgress,
    clearance_speed_scale,
    resolve_task,
    validate_routes,
)


CONTROL_HZ = 20.0
STEP_SECONDS = 1.0 / CONTROL_HZ
LINEAR_SPEED = 0.08
TURN_SPEED = 0.5
STOP_DISTANCE = 0.4
SLOW_DISTANCE = 0.8


def simulate_route(route, clearance_by_step):
    elapsed = 0.0
    travelled = []
    for index, step in enumerate(route["steps"]):
        action = str(step["action"]).lower()
        progress = StepProgress()
        clearance = float(clearance_by_step[index])
        while not progress.complete(step):
            if action in LINEAR_ACTIONS:
                scale = clearance_speed_scale(clearance, STOP_DISTANCE, SLOW_DISTANCE)
                if scale <= 0.0:
                    return {
                        "status": "blocked",
                        "reason": "lidar_stop_%.2fm" % clearance,
                        "step": index,
                        "elapsed_s": round(elapsed, 3),
                        "progress": round(progress.value, 3),
                    }
                progress.add_motion(action, LINEAR_SPEED * scale, 0.0, STEP_SECONDS)
            elif action in ROTATE_ACTIONS:
                if clearance <= 0.3:
                    return {
                        "status": "blocked",
                        "reason": "lidar_rotation_stop_%.2fm" % clearance,
                        "step": index,
                        "elapsed_s": round(elapsed, 3),
                        "progress": round(progress.value, 3),
                    }
                progress.add_motion(action, 0.0, TURN_SPEED, STEP_SECONDS)
            else:
                progress.add_motion(action, 0.0, 0.0, STEP_SECONDS)
            elapsed += STEP_SECONDS
        travelled.append(round(progress.value, 3))
    return {
        "status": "done",
        "reason": "route_complete",
        "elapsed_s": round(elapsed, 3),
        "step_progress": travelled,
    }


def expect_value_error(operation, expected_text):
    try:
        operation()
    except ValueError as exc:
        if expected_text not in str(exc):
            raise AssertionError("错误内容不符合预期：%s" % exc) from exc
        return str(exc)
    raise AssertionError("预期出现 ValueError")


def main():
    lab_dir = Path(__file__).parent
    document = json.loads((lab_dir / "routes.json").read_text(encoding="utf-8"))
    routes = validate_routes(document)

    clear_result = simulate_route(routes["R1"], [2.0, 2.0, 2.0])
    if clear_result["status"] != "done":
        raise AssertionError("无遮挡路线应当完成")

    slow_result = simulate_route(routes["R1"], [0.6, 2.0, 0.6])
    if slow_result["status"] != "done":
        raise AssertionError("减速路线应当完成")
    if slow_result["elapsed_s"] <= clear_result["elapsed_s"]:
        raise AssertionError("减速路线耗时应当增加")
    if slow_result["step_progress"][0] < 0.3 or slow_result["step_progress"][2] < 0.3:
        raise AssertionError("减速路线必须累计到目标距离")

    blocked_result = simulate_route(routes["R1"], [0.35, 2.0, 2.0])
    if blocked_result["status"] != "blocked":
        raise AssertionError("障碍场景应当停止")

    route_id, steps, deadline = resolve_task({
        "task_id": "SIM-VALID-1",
        "robot": "robot1",
        "zone": "entrance",
        "route": "R1",
        "deadline_s": 60,
    }, "robot1", routes)
    if route_id != "R1" or len(steps) != 3 or deadline != 60:
        raise AssertionError("有效任务解析结果不完整")

    wrong_robot = expect_value_error(lambda: resolve_task({
        "task_id": "SIM-WRONG-ROBOT",
        "robot": "robot2",
        "zone": "entrance",
        "route": "R1",
    }, "robot1", routes), "wrong_robot")

    wrong_route = expect_value_error(lambda: resolve_task({
        "task_id": "SIM-WRONG-ROUTE",
        "robot": "robot1",
        "zone": "entrance",
        "route": "R4",
    }, "robot1", routes), "route_zone_mismatch")

    expected_clear_time = 0.3 / LINEAR_SPEED * 2 + math.radians(90) / TURN_SPEED
    report = {
        "kind": "simulation",
        "notice": "本文件仅记录离线逻辑模拟，不代表真车验收证据。",
        "configuration": {
            "control_hz": CONTROL_HZ,
            "linear_speed_mps": LINEAR_SPEED,
            "turn_speed_radps": TURN_SPEED,
            "stop_distance_m": STOP_DISTANCE,
            "slow_distance_m": SLOW_DISTANCE,
        },
        "scenarios": {
            "clear_route": clear_result,
            "slow_route": slow_result,
            "blocked_route": blocked_result,
            "valid_task": {"route": route_id, "steps": len(steps), "deadline_s": deadline},
            "wrong_robot": wrong_robot,
            "route_zone_mismatch": wrong_route,
        },
        "reference_clear_time_s": round(expected_clear_time, 3),
        "verdict": "PASS",
    }
    output = lab_dir / "simulation-report.json"
    output.write_text(json.dumps(report, ensure_ascii=False, indent=2), encoding="utf-8")
    print(json.dumps(report, ensure_ascii=False, indent=2))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

