    seen.push(r);
    say(`  回执 ${r.status}  reason=${r.reason}`);
    if (r.status === 'cancelled') cancelled = r;
  });
  bridge.subscribe(T.cmd, 'geometry_msgs/msg/Twist', (m) => {
    const linear = m.linear || {};
    const angular = m.angular || {};
    velocities.push(Math.hypot(
      Number(linear.x || 0), Number(linear.y || 0), Number(linear.z || 0),
      Number(angular.x || 0), Number(angular.y || 0), Number(angular.z || 0),
    ));
  });
  publishString(bridge, T.control, { cmd: 'cancel', reason: 'operator_cancel', task_id: taskId });
  const t0 = nowMs();
  while ((!cancelled || velocities.length < 3) && nowMs() - t0 < 10000) await sleep(200);
  bridge.close();
  const verdict = cancelVerdict({ taskId, cancelled, velocities }) ? 'PASS' : 'FAIL';
  saveEvidence('cancel', { at: new Date().toISOString(), car, task_id: taskId, verdict, seen, velocities });
  say(`E5 取消任务：${verdict}`);
  return verdict === 'PASS' ? 0 : 1;
}

